    return () => window.removeEventListener('resize', update)
  }, [])

  const newsItems = [
    {
      tag: 'Disaster Response',
      title: 'Hurricane Response Update',
      description: 'Global Aid Alliance teams are providing shelter and supplies to over 15,000 families displaced by Hurricane Marlena along the Gulf Coast. Relief operations are ongoing across 12 counties.',
      image: 'https://images.unsplash.com/photo-1544027993-37dbfe43562a?w=600&h=400&fit=crop',
    },
    {
      tag: 'Wildfire Relief',
      title: 'Wildfire Relief Efforts',
      description: 'Emergency shelters have been opened in three western states as crews battle record-breaking wildfires. Volunteers are distributing meals, water, and comfort kits to evacuees.',
