    },
    {
      tag: 'Volunteer Story',
      title: 'Volunteer Spotlight',
      description: 'Meet Daniela Torres, a disaster response volunteer who has deployed to seven emergencies in three years. Her story of service inspires communities across the country.',
      image: 'https://images.unsplash.com/photo-1559027615-cd4628902d4a?w=600&h=400&fit=crop',
    },
  ]

  const maxIndex = Math.max(0, newsItems.length - itemsPerPage)

  const next = () => setCurrentIndex((prev) => Math.min(prev + 1, maxIndex))
