                <p className="text-white/70 text-sm leading-relaxed">{item.impact}</p>
              </motion.div>
            ))}
          </div>

          <Button
            onClick={onDonate}
            size="lg"
            className="bg-white text-primary hover:bg-warm-gray font-bold px-10 py-6 text-lg rounded-xl transition-all shadow-xl"
