/* ──────────── Donate Modal ──────────── */
function DonateModal({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  const [selectedAmount, setSelectedAmount] = useState<string | null>('50')
  const [customAmount, setCustomAmount] = useState('')

  const presetAmounts = ['25', '50', '100', '250', '500', '1000']

  const handleAmountClick = (amount: string) => {
    setSelectedAmount(amount)
    setCustomAmount('')
  }

  const handleCustomChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCustomAmount(e.target.value)
    setSelectedAmount(null)
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md bg-white">
        <DialogHeader>
          <DialogTitle className="font-heading text-2xl text-text-heading">Make a Donation</DialogTitle>
          <DialogDescription className="text-text-muted">
            Your gift helps us respond to disasters and support communities in crisis.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-6 pt-4">
          <div className="grid grid-cols-3 gap-3">
            {presetAmounts.map((amount) => (
              <button
                key={amount}
                onClick={() => handleAmountClick(amount)}
                className={`py-3 rounded-lg font-heading font-semibold text-lg border-2 transition-all ${
                  selectedAmount === amount
                    ? 'border-primary bg-primary text-white'
                    : 'border-border bg-warm-gray text-text-heading hover:border-primary/50'
                }`}
              >
                ${amount}
              </button>
            ))}
          </div>
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-text-muted font-heading text-lg">$</span>
            <input
              type="number"
              placeholder="Custom amount"
              value={customAmount}
              onChange={handleCustomChange}
              className="w-full pl-8 pr-4 py-3 rounded-lg border-2 border-border bg-warm-gray font-heading text-lg text-text-heading placeholder:text-text-muted focus:border-primary focus:outline-none transition-colors"
            />
          </div>
          <Button
            onClick={() => onOpenChange(false)}
            className="w-full bg-primary hover:bg-primary-dark text-white font-bold py-6 text-base rounded-xl"
          >
            <Heart className="w-5 h-5 mr-2" />
            Donate {selectedAmount ? `$${selectedAmount}` : customAmount ? `$${customAmount}` : ''}
          </Button>
          <p className="text-xs text-text-muted text-center">
            91 cents of every dollar goes directly to humanitarian services. Your donation is tax-deductible.
          </p>
        </div>
      </DialogContent>
    </Dialog>
  )
}

